'use strict'

const ChannelSubscriber = require('../channel-base')

// NR's hapi channels fire at route/extension registration time, not at request
// handling time. Security events for hapi applications are generated by the
// database subscribers using the request context stored by the http hook.
// These subscribers complete the channel-only coverage without generating events.

class HapiRouteSubscriber extends ChannelSubscriber {
  constructor() {
    super({ packageName: '@hapi/hapi', channelName: 'nr_route' })
  }

  extractArgs() {
    return null
  }
}

class HapiExtSubscriber extends ChannelSubscriber {
  constructor() {
    super({ packageName: '@hapi/hapi', channelName: 'nr_ext' })
  }

  extractArgs() {
    return null
  }
}

module.exports = { HapiRouteSubscriber, HapiExtSubscriber }
